                    Tracked(Commit(mpt))
                });

                let value = entry.unwrap().1;
                handle1x.release_read();
                handle2x.release_read();
                return Some(value);
            }

            i += 1;
        }

        try_open_atomic_update!(au, mpt => {
            proof {
                if l1 < l2 {
                    self.instance.query_none(key, &mpt,
                        &handle1x.borrow().rows.tracked_borrow(h1x as nat).token,
