                main_handle.release_write(Tracked(()));
                try_open_atomic_update!(au, mpt => { Tracked(Commit(mpt)) });
                return false;
            }
            i -= 1;

            proof {
                assert(places_ok(path@, path.len() - 2));
                assert(forall |i: int| 0 <= i && i+1 < old_path.len() ==>
                    places_ok(old_path@, i) ==> places_ok(path@, i));
            }
        }

