/// Release the write-lock. Update the 'exc' bit back to 'false'.
/// Return the 'writer' and also deposit an object back into storage.
transition!{
    release_exc(x: V) {
        require Pred::inv(pre.k, x);
        remove writer -= Some(());

        update flag_exc = false;

        deposit storage += Some(x);
    }
}

